import * as XLSX from 'xlsx';

/**
 * Service pour l'export des desiderata au format Excel
 * Génère un fichier avec une feuille par médecin
 */

/**
 * Exporte les desiderata de tous les médecins vers un fichier Excel
 * @param {Array} medecins - Liste des médecins
 * @param {Array} desiderataList - Liste des desiderata
 * @param {Object} periode - Période de saisie {startDate, endDate}
 */
export const exportDesiderataToExcel = async (medecins, desiderataList, periode) => {
  try {
    // Créer un nouveau workbook
    const workbook = XLSX.utils.book_new();

    // Générer le nom de fichier basé sur la période
    const fileName = generateFileName(periode);

    // Pour chaque médecin, créer une feuille
    for (const medecin of medecins) {
      const medecinDesiderata = desiderataList.find(d => d.userId === medecin.id);
      const worksheetData = generateMedecinWorksheetData(medecin, medecinDesiderata, periode);

      // Créer la feuille de calcul
      const worksheet = XLSX.utils.aoa_to_sheet(worksheetData);

      // Appliquer le formatage
      applyWorksheetFormatting(worksheet, worksheetData);

      // Nom de la feuille (limité à 31 caractères pour Excel)
      const sheetName = `${medecin.nom} ${medecin.prenom}`.substring(0, 31);

      // Ajouter la feuille au workbook
      XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);
    }

    // Télécharger le fichier
    XLSX.writeFile(workbook, fileName);
    return {
      success: true,
      fileName: fileName,
      message: `Export Excel généré avec succès : ${fileName}`
    };
  } catch (error) {
    console.error('Erreur lors de l\'export Excel:', error);
    throw error;
  }
};

/**
 * Génère le nom de fichier basé sur la période
 * @param {Object} periode - {startDate, endDate}
 * @returns {string} - Nom du fichier
 */
const generateFileName = periode => {
  if (!periode || !periode.startDate || !periode.endDate) {
    return 'DESIDERATA_EXPORT.xlsx';
  }
  const startDate = new Date(periode.startDate);
  const endDate = new Date(periode.endDate);

  // Extraire les mois et années
  const startMonth = startDate.toLocaleDateString('fr-FR', {
    month: 'short'
  }).toUpperCase();
  const startYear = startDate.getFullYear();
  const endMonth = endDate.toLocaleDateString('fr-FR', {
    month: 'short'
  }).toUpperCase();
  const endYear = endDate.getFullYear();

  // Format: DESIDERATA NDJ25-26.xlsx (pour Nov-Déc-Jan 2025-2026)
  if (startYear === endYear) {
    return `DESIDERATA ${startMonth}${endMonth}${startYear.toString().slice(-2)}.xlsx`;
  } else {
    return `DESIDERATA ${startMonth}${startYear.toString().slice(-2)}-${endMonth}${endYear.toString().slice(-2)}.xlsx`;
  }
};

/**
 * Génère les données de la feuille pour un médecin
 * @param {Object} medecin - Données du médecin
 * @param {Object} desiderata - Desiderata du médecin
 * @param {Object} periode - Période de saisie
 * @returns {Array} - Tableau 2D pour la feuille Excel
 */
const generateMedecinWorksheetData = (medecin, desiderata, periode) => {
  const data = [];

  // En-tête avec nom du médecin
  data.push([`Dr ${medecin.prenom} ${medecin.nom.toUpperCase()}`]);
  data.push([`Email: ${medecin.email}`]);
  data.push(['']); // Ligne vide

  // Période
  if (periode && periode.startDate && periode.endDate) {
    const startDate = new Date(periode.startDate).toLocaleDateString('fr-FR');
    const endDate = new Date(periode.endDate).toLocaleDateString('fr-FR');
    data.push([`Période: ${startDate} - ${endDate}`]);
  }
  data.push(['']); // Ligne vide

  // Informations générales des desiderata
  if (desiderata) {
    data.push(['INFORMATIONS GÉNÉRALES']);
    data.push(['Nombre de gardes souhaitées:', desiderata.nombreGardesSouhaitees || 'Non spécifié']);
    data.push(['Nombre max de gardes par semaine:', desiderata.nombreGardesMaxParSemaine || 'Non spécifié']);
    data.push(['Gardes groupées:', desiderata.gardesGroupees ? 'Oui' : 'Non']);
    data.push(['Renforts associés:', desiderata.renfortsAssocies ? 'Oui' : 'Non']);
    data.push(['']); // Ligne vide

    // En-têtes pour le tableau des créneaux
    data.push(['CRÉNEAUX SOUHAITÉS']);
    data.push(['Date', 'Jour', 'Créneau', 'Disponibilité']);

    // Générer les lignes de créneaux
    if (desiderata.desiderata && Object.keys(desiderata.desiderata).length > 0) {
      const creneauxData = generateCreneauxData(desiderata.desiderata);
      data.push(...creneauxData);
    } else {
      data.push(['Aucun créneau spécifié', '', '', '']);
    }
  } else {
    data.push(['AUCUN DESIDERATA SAISI']);
    data.push(['Ce médecin n\'a pas encore saisi ses desiderata.']);
  }
  return data;
};

/**
 * Génère les données des créneaux à partir de l'objet desiderata
 * @param {Object} desiderata - Objet contenant les créneaux
 * @returns {Array} - Tableau des lignes de créneaux
 */
const generateCreneauxData = desiderata => {
  const creneaux = [];
  Object.entries(desiderata).forEach(([dateKey, dayData]) => {
    if (dayData && typeof dayData === 'object') {
      const date = new Date(dateKey);
      const dateStr = date.toLocaleDateString('fr-FR');
      const dayName = date.toLocaleDateString('fr-FR', {
        weekday: 'long'
      });
      Object.entries(dayData).forEach(([creneauKey, disponibilite]) => {
        // Traduire les créneaux en français
        const creneauLabel = translateCreneauKey(creneauKey);
        const disponibiliteLabel = translateDisponibilite(disponibilite);
        creneaux.push([dateStr, dayName, creneauLabel, disponibiliteLabel]);
      });
    }
  });
  return creneaux.length > 0 ? creneaux : [['Aucun créneau spécifié', '', '', '']];
};

/**
 * Traduit les clés de créneaux en labels français
 * @param {string} key - Clé du créneau
 * @returns {string} - Label en français
 */
const translateCreneauKey = key => {
  const translations = {
    'nuit': 'Nuit (19h-8h)',
    'matin': 'Matin (8h-19h)',
    'weekend': 'Week-end',
    'jour': 'Jour',
    'garde': 'Garde'
  };
  return translations[key] || key;
};

/**
 * Traduit les valeurs de disponibilité
 * @param {string} value - Valeur de disponibilité
 * @returns {string} - Label traduit
 */
const translateDisponibilite = value => {
  const translations = {
    'disponible': 'Disponible',
    'indisponible': 'Indisponible',
    'prefere': 'Préféré',
    'eviter': 'À éviter',
    true: 'Oui',
    false: 'Non'
  };
  return translations[value] || value || 'Non spécifié';
};

/**
 * Applique le formatage à la feuille Excel
 * @param {Object} worksheet - Feuille de calcul
 * @param {Array} data - Données de la feuille
 */
const applyWorksheetFormatting = (worksheet, data) => {
  // Définir la largeur des colonnes
  const colWidths = [{
    wch: 12
  },
  // Date
  {
    wch: 12
  },
  // Jour
  {
    wch: 20
  },
  // Créneau
  {
    wch: 15
  } // Disponibilité
  ];
  worksheet['!cols'] = colWidths;

  // Auto-ajuster la hauteur des lignes
  worksheet['!rows'] = data.map(() => ({
    hpt: 20
  }));

  // Appliquer des styles basiques (les styles avancés nécessitent xlsx-style ou exceljs)
  // Pour l'instant, on garde la fonctionnalité de base
};

/**
 * Obtient les statistiques d'export
 * @param {Array} medecins - Liste des médecins
 * @param {Array} desiderataList - Liste des desiderata
 * @returns {Object} - Statistiques
 */
export const getExportStatistics = (medecins, desiderataList) => {
  const totalMedecins = medecins.length;
  const medecinsSaisi = desiderataList.filter(d => d.desiderata && Object.keys(d.desiderata).length > 0).length;
  const medecinsNonSaisi = totalMedecins - medecinsSaisi;
  return {
    totalMedecins,
    medecinsSaisi,
    medecinsNonSaisi,
    pourcentageSaisi: totalMedecins > 0 ? Math.round(medecinsSaisi / totalMedecins * 100) : 0
  };
};

